@media (width >= 1101px) and (width <= 1280px) {
  .header-redesign .site-nav-inner { gap: 0px 14px; }
  .header-redesign .nav-brand-copy small { max-width: 170px; display: block; }
  .header-redesign .nav-action-search span, .header-redesign .nav-action-submit span, .header-redesign .nav-quick-trigger span { display: inline; }
